function makeBlock(w, h, d, mat, x, y, z) {
  const geom = new THREE.BoxGeometry(w, h, d);
  const mesh = new THREE.Mesh(geom, mat);
  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(geom), lineMat);
  mesh.add(edges);
  mesh.position.set(x, y, z);
  scene.add(mesh);
  return mesh;
}

function makeRect(w, h, mat, x, y, z = 0) {
  const geom = new THREE.PlaneGeometry(w, h);
  const mesh = new THREE.Mesh(geom, mat);
  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(geom), lineMat);
  mesh.add(edges);
  mesh.position.set(x, y, z);
  scene.add(mesh);
  return mesh;
}

function addArrowLine(p1, p2) {
  const pts = [p1, p2];
  scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), lineMat));
  const dir = new THREE.Vector3().subVectors(p2, p1).normalize();
  if (dir.lengthSq() < 0.01) return;
  const right = new THREE.Vector3(-dir.y, dir.x, 0).multiplyScalar(0.12);
  const back = dir.clone().multiplyScalar(-0.24);
  const h1 = p2.clone().add(back).add(right);
  const h2 = p2.clone().add(back).sub(right);
  scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([h1, p2, h2]), lineMat));
}

function addDots(x, y, z1, z2, n) {
  const geom = new THREE.SphereGeometry(0.04, 8, 8);
  const mat = new THREE.MeshBasicMaterial({ color: 0x444444 });
  for (let i = 0; i < n; i++) {
    const z = z1 + (z2 - z1) * (i + 1) / (n + 1);
    const mesh = new THREE.Mesh(geom, mat);
    mesh.position.set(x, y, z);
    scene.add(mesh);
  }
}

// 2. MACRO ARCHITECTURE (BOTTOM)
