makeBlock(0.3, 0.6, 1.0, matStage, 5.0, -2.2, 1.2);
makeBlock(0.3, 0.6, 1.0, matStage, 5.0, -2.2, 2.4);

// Output FC (2 thin columns)
makeBlock(0.1, 2.5, 0.1, matFC, 7.5, -1.25, 0);
makeBlock(0.1, 2.5, 0.1, matFC, 7.9, -1.25, 0);
addDots(7.7, -1.25, 0, 0, 3); // Dots between FC layers

// Macro Arrows
addArrowLine(new THREE.Vector3(-7.8, -1.25, 0), new THREE.Vector3(-6.8, -1.25, 0)); // Img -> Conv
addArrowLine(new THREE.Vector3(-6.2, -1.25, 0), new THREE.Vector3(-5.95, -1.25, 0)); // Conv -> Pool
addArrowLine(new THREE.Vector3(-5.65, -1.25, 0), new THREE.Vector3(-4.8, -1.25, 0)); // Pool -> S1
