makeRect(0.6, 0.6, matInReLU, 4.4, iy);
makeRect(1.2, 0.6, matInConv, 5.9, iy);

// Inset Plus Symbol
const plusGeom = new THREE.CircleGeometry(0.3, 32);
const plusMesh = new THREE.Mesh(plusGeom, matWhite);
plusMesh.position.set(7.1, iy, 0);
scene.add(plusMesh);
scene.add(new THREE.LineSegments(new THREE.EdgesGeometry(plusGeom), lineMat));
const plusLines = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(6.95, iy, 0.02), new THREE.Vector3(7.25, iy, 0.02),
