addLabel('Conv 1&times;1', new THREE.Vector3(5.9, iy, 0), lblSm);

const cOpts = { fontSize: '12px', color: '#0055aa', bold: true };
const lblIn = addLabel('256', new THREE.Vector3(-6.1, iy + 0.35, 0), cOpts);
const lblC1 = addLabel('64', new THREE.Vector3(-1.8, iy + 0.35, 0), cOpts);
