const lblOut = addLabel('256', new THREE.Vector3(7.6, iy + 0.35, 0), cOpts);

function updateInset(inCh, innerCh, outCh) {
  lblIn.div.innerHTML = inCh;
  lblC1.div.innerHTML = innerCh;
  lblC2.div.innerHTML = innerCh;
  lblC3.div.innerHTML = outCh;
  lblOut.div.innerHTML = outCh;
