// 5. INTERACTIVITY: Clickable Hitboxes for Stages
function addHitbox(x, y, w, h, stageName, inCh, innerCh, outCh) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, 3), new THREE.MeshBasicMaterial({ visible: false }));
  mesh.position.set(x, y, 1.2);
  scene.add(mesh);
  registerInteractive(mesh, {
    title: stageName,
    tooltip: `Click to load ${stageName} channels into inset`,
    onClick: () => updateInset(inCh, innerCh, outCh)
  });
}
addHitbox(-4.5, -1.5, 2, 2.5, 'Stage 1', 64, 64, 256);
addHitbox(-2.0, -1.75, 2, 2.5, 'Stage 2', 256, 128, 512);
addHitbox(1.5, -2.0, 2, 2.0, 'Stage 3', 512, 256, 1024);
addHitbox(5.0, -2.2, 2, 1.5, 'Stage 4', 1024, 512, 2048);

// 6. INTERACTIVITY: Forward Pass Animation
const dotMat = new THREE.MeshBasicMaterial({ color: 0xFFD700 });
const dot1 = new THREE.Mesh(new THREE.CircleGeometry(0.15, 16), dotMat);
const dot2 = new THREE.Mesh(new THREE.CircleGeometry(0.15, 16), dotMat);
dot1.position.z = 0.05; dot2.position.z = 0.05;
scene.add(dot1);
scene.add(dot2);
dot1.visible = false; dot2.visible = false;

let isAnim = false;
let animT = 0;

document.getElementById('btnAnim').addEventListener('click', () => {
  if (!isAnim) {
    isAnim = true;
    animT = 0;
    dot1.visible = true;
    dot2.visible = true;
  }
});

function customRenderLoop() {
  requestAnimationFrame(customRenderLoop);
  if (isAnim) {
    animT += 0.008;
    if (animT >= 1) {
      animT = 1;
      isAnim = false;
      setTimeout(() => { dot1.visible = false; dot2.visible = false; }, 300);
    }

    // Main path dot (straight across)
    dot1.position.set(-6.0 + animT * 13.5, iy, 0.05);

    // Skip path dot
    if (animT < 0.15) {
      dot2.position.set(-6.0, iy + (animT / 0.15) * 1.2, 0.05);
    } else if (animT < 0.85) {
      dot2.position.set(-6.0 + ((animT - 0.15) / 0.7) * 13.1, iy + 1.2, 0.05);
    } else {
      dot2.position.set(7.1, iy + 1.2 - ((animT - 0.85) / 0.15) * 1.2, 0.05);
    }
  }
